export const CONTROL_PACKS=packs;
const byId=new Map(packs.map(p=>[p[0],p]));
const baseByCategory:Record<string,string>={'Mechanical':'ROT','Electrical':'ELE','Work at height':'FALL','Slips and trips':'SLIP','Transport':'VEH','Lifting':'LIFT','Fire and explosion':'FIRE','Chemicals':'TOX','Pressure':'PRS','Thermal':'HOT','Physical agents':'NOISE','Biological':'BIO','Ergonomics':'ERG','Confined spaces':'ASPH','Construction':'STRUCT','Psychosocial':'PSY','Environment':'WEATHER','Process safety':'PROC','Human factors':'HUM','Security':'SEC','Specialist operations':'SPEC'};
type Hazard={code?:unknown;label?:unknown;category?:unknown;subcategory?:unknown;energySourceCode?:unknown};
export function mechanisms(h:Hazard):string[]{
 const label=String(h.label||'').toLowerCase(),cat=String(h.category||''),sub=String(h.subcategory||'').toLowerCase(),code=String(h.code||'');
 const ids=new Set<string>();const add=(...v:string[])=>v.forEach(x=>ids.add(x));
 // Select by credible mechanism, not just lexical similarity across unrelated categories.
 if(cat==='Mechanical'||cat==='Lifting'||cat==='Specialist operations'){
  if(/entangl|rotat|shaft|spindle|auger|conveyor|flywheel|coupling|belt|chain|impeller|rotor|propeller|web reel|gear/.test(label))add('ROT');
  if(/crush|trap|shear|nip|press|ram|robot|actuat|closing|moving|brake|clamp|gripper/.test(label))add('CRU');
  if(/spring|torsion|snapback|tension|prestress|cable reel/.test(label))add('SPR');
  if(/cut|blade|saw|knife|sharp|grinding/.test(label))add('CUT');
 }
 if(cat==='Electrical'||/electr|battery|capacitor|arc flash|arc blast|solar pv|tra[c]tion power/.test(label)){if(cat==='Electrical'||/electrical|electric shock|solar pv|battery|capacitor|arc flash|arc blast/.test(label))add('ELE');if(/arc|switchgear|fault current|busbar|high voltage/.test(label))add('ARC');if(/battery|capacitor|dc link|stored charge|supercapacitor/.test(label))add('BAT');}
 if(cat==='Lifting'||/suspended load|raised |elevated machine|counterweight|falling object|magnetic lifting|vacuum lifting/.test(label))add('GRV');
 if(/hydraulic|fluid injection/.test(label))add('HYD');
 if(/pneumatic|compressed air|air receiver|air spring|air injection|air header|plant air|instrument air|blow moulding air|high-pressure air|air operated/.test(label))add('PNE');
 if(cat==='Pressure'||/pressure vessel|pressurized|steam line|boiler|gas cylinder|wellhead/.test(label)){if(!ids.has('HYD')&&!ids.has('PNE'))add('PRS');}
 if(/vacuum|implosion|suction/.test(label))add('VAC');
 if(/high.pressure water jet|waterjet|water jet|abrasive blast|ultra.high.pressure cleaning/.test(label))add('JET');
 if(cat==='Thermal'||/steam|hot |molten|furnace|kiln|thermal oil|boiler|scald/.test(label)){if(!/cold|cryogen|frost|freezer|liquid nitrogen|liquid oxygen|dry ice/.test(label))add('HOT');}
 if(/cryogen|frost|freezer|cold stress|cold burn|liquid nitrogen|liquid oxygen|dry ice|hypotherm|refrigerant|refrigerat|chilled/.test(label))add('COLD');
 if(/acid|caustic|corrosiv|cip|electrolyte|chlorinated cleaning/.test(label))add('ACID');
 if(cat==='Chemicals'||/toxic|poison|ammonia|chlorine|carbon monoxide|hydrogen sulphide|solvent|fume|pesticide|refrigerant/.test(label)){if(!ids.has('ACID')||/inhal|vapour|fume|ammonia|chlorine/.test(label))add('TOX');}
 if(/dust|silica|asbestos|fibre|particulate|powder/.test(label)){if(cat!=='Environment'||/dust/.test(label))add('DUST');}
 if(/flamm|fuel|ignition|fire|combust|thermal runaway|lpg|hydrogen|biogas|solvent/.test(label)&&!(/firewater|fire escape|fire protection/.test(label)))add('FIRE');
 if(/explos|blast|deflagrat|runaway reaction|pyrotechnic/.test(label))add('EXP');
 if(/reacti|incompatib|peroxide|polymeriz|exotherm/.test(label))add('REACT');
 if(/oxygen enrich|oxidiz|oxidis|medical oxygen|oxygen distribution|liquid oxygen/.test(label))add('OXY');
 if(/asphyx|oxygen deficien|inert|nitrogen|argon|helium|carbon dioxide|confined space|gas accumulation/.test(label)||cat==='Confined spaces')add('ASPH');
 if(cat==='Work at height'||/fall from|fall into|unprotected edge|roof edge/.test(label))add('FALL');
 if(cat==='Slips and trips')add('SLIP');
 if(cat==='Transport'||/forklift collision|vehicle collision|runover|traffic route|jet blast/.test(label))add('VEH');
 if(cat==='Lifting'&&!ids.has('GRV'))add('LIFT');
 if(/noise|acoustic|hearing|ultrasound|sound source/.test(label))add('NOISE');
 if(/vibrat/.test(label))add('VIB');
 if(/ionizing|radioactiv|radiograph|x.ray|gamma|neutron|nuclear|radon|electron beam|particle accelerator/.test(label)&&!/non.ionizing/.test(label))add('RAD');
 if(/laser|ultraviolet|uv.c|uv curing|uv disinfection|optical radiation|infrared|glare|high intensity light|led array|germicidal/.test(label))add('OPT');
 if(/radiofrequen|microwave|magnetic|electromagnetic|radar|rf |induction heat|induction melt|mri/.test(label))add('EMF');
 if(cat==='Biological'||/pathogen|infection|legionella|bioaerosol|bloodborne|infectious|contaminated wastewater|sewage/.test(label))add('BIO');
 if(/needle|sharps|medical sharp/.test(label))add('SHARP');
 if(cat==='Ergonomics'||/manual handling|manual lift|awkward posture|repetitive motion/.test(label))add('ERG');
 if(cat==='Construction'||/structural collapse|ground collapse|rock burst|trench|excavat|roof collapse|rockfall|shoring|tunnel|prestressed/.test(label))add('STRUCT');
 if(/engulf|burial|drown|flood|silo|material bridging|avalanche/.test(label))add('ENGULF');
 if(cat==='Environment'||/lightning|extreme weather|wildfire|storm|heat stress|heatstroke/.test(label))add('WEATHER');
 if(cat==='Psychosocial'||/fatigue|bullying|harassment|workplace violence|traumatic incident/.test(label))add('PSY');
 if(cat==='Process safety')add('PROC');
 if(cat==='Human factors')add('HUM');
 if(cat==='Security')add('SEC');
 if(/glass bottle|glass break|brittle fragment|bottle explosion/.test(label))add('GLASS');
 if(/food product contamination|foodborne|allergen|process contamination/.test(label))add('FOOD');
 if(/marine|diving|hyperbaric|overboard|mooring|ship dry dock|vessel collision|offshore personnel/.test(label))add('MAR');
 // Source family is still considered if no specific mechanism was triggered.
 if(!ids.size){if(code.startsWith('SAF_03_09_'))add('OPT','EMF');else if(code.startsWith('SAF_03_05_'))add('PNE');else if(code.startsWith('SAF_03_04_'))add('HYD');else add(baseByCategory[cat]||'SPEC');}
 // The catalogue remains a candidate library. No injury is asserted to be inevitable.
 return [...ids].filter(id=>byId.has(id));
}
export function hazardControlProfile(h:Hazard){
 const ids=mechanisms(h),selected=ids.map(id=>byId.get(id)!);
 const injuries=selected.flatMap(([id,title,items])=>items.map((label,i)=>({code:'INJ-'+id+'-'+String(i+1).padStart(2,'0'),label,mechanism:title})));
 const layers=CONTROL_HIERARCHY.map((layer,index)=>({...layer,measures:selected.flatMap(pack=>pack[index+3] instanceof Array?(pack[index+3] as string[]).map((label,i)=>({code:'CTL-'+pack[0]+'-'+layer.code+'-'+String(i+1).padStart(2,'0'),label,mechanism:pack[1]})):[])}));
 return {hazardCode:String(h.code||''),hazardLabel:String(h.label||''),mechanisms:selected.map(p=>({code:p[0],label:p[1]})),injuries,layers,reviewRequired:true,referenceBasis:['NIOSH Hierarchy of Controls','OSHA Job Hazard Analysis — hazard and control evaluation'],schemaVersion:1};
}
